            out_path=args.evidence_out,
            pkg_path=pkg_path,
            runner_script=str(runner_path),
            python=args.python,
            cmd=invocation_cmd,
            exclude_dirs=exclude_dirs,
            all_funcs=all_funcs,
            all_obs_ids=all_observed_ids,
