</div>""")
    all_baselines_html = "\n".join(baseline_cards_html)

    # Map rows HTML
    map_rows_html = []
    for mod_label, funcs in sorted_modules:
        cells = []
        for fn in funcs:
            prov = fn["provenance"]
            if prov == PROVENANCE_IN_SITU:
