    </div>
    <div class="ctx-item">
      <span class="ctx-item__num">{e(str(prod_insitu_count))}</span>
      <span class="ctx-item__word">in-situ (product)</span>
    </div>
    <div class="ctx-item">
      <span class="ctx-item__num">{e(str(prod_driver_count))}</span>
