  </div>
</header>

<hr class="sep">

<!-- ═══════════════════════════════════════════════════════
     SECTION 2 — BASELINE
     ═══════════════════════════════════════════════════════ -->
<section class="baseline">
  <div class="label">Baseline — exactly what was executed</div>
  <div class="baseline__grid">
    <span class="baseline__key">runner</span>
