</head>
<body>

<!-- ═══════════════════════════════════════════════════════
     SECTION 1 — HEADLINE NUMBER
     ═══════════════════════════════════════════════════════ -->
<header class="headline">
  <span class="label">First Light &mdash; Function Observation Report</span>
  <span class="headline__never">{e(str(prod_never))}</span>
