def _sha256(path: str) -> str:
    """Return the hex SHA-256 of a file's current contents."""
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def write_evidence(
    out_path: str,
    pkg_path: Path,
    runner_script: str,
    python: str,
    cmd: list[str],
    exclude_dirs: set[str],
    all_funcs: list[FuncInfo],
    all_obs_ids: set[int],
